"use strict";(self.webpackChunkbackpacked_documentation=self.webpackChunkbackpacked_documentation||[]).push([[140],{7271:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Custom Backpacks","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Introduction","href":"/Backpacked/docs/custom-backpack/introduction","docId":"custom-backpack/introduction","unlisted":false},{"type":"link","label":"Getting Started","href":"/Backpacked/docs/custom-backpack/getting-started","docId":"custom-backpack/getting-started","unlisted":false},{"type":"link","label":"Register a New Backpack","href":"/Backpacked/docs/custom-backpack/register-the-backpack","docId":"custom-backpack/register-the-backpack","unlisted":false},{"type":"link","label":"Creating the Model","href":"/Backpacked/docs/custom-backpack/creating-the-model","docId":"custom-backpack/creating-the-model","unlisted":false},{"type":"link","label":"Model Metadata","href":"/Backpacked/docs/custom-backpack/model-metadata","docId":"custom-backpack/model-metadata","unlisted":false},{"type":"link","label":"Translations","href":"/Backpacked/docs/custom-backpack/translations","docId":"custom-backpack/translations","unlisted":false},{"type":"category","label":"Unlock Challenges","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Introduction","href":"/Backpacked/docs/custom-backpack/unlock-challenges/introduction","docId":"custom-backpack/unlock-challenges/introduction","unlisted":false},{"type":"link","label":"Creating the Challenge","href":"/Backpacked/docs/custom-backpack/unlock-challenges/creating-the-challenge","docId":"custom-backpack/unlock-challenges/creating-the-challenge","unlisted":false},{"type":"link","label":"Challenge Types","href":"/Backpacked/docs/custom-backpack/unlock-challenges/challenge-types","docId":"custom-backpack/unlock-challenges/challenge-types","unlisted":false},{"type":"link","label":"Formatter Types","href":"/Backpacked/docs/custom-backpack/unlock-challenges/formatter-types","docId":"custom-backpack/unlock-challenges/formatter-types","unlisted":false},{"type":"link","label":"Predicates","href":"/Backpacked/docs/custom-backpack/unlock-challenges/predicates","docId":"custom-backpack/unlock-challenges/predicates","unlisted":false}]},{"type":"link","label":"Advanced Rendering","href":"/Backpacked/docs/custom-backpack/advanced-rendering","docId":"custom-backpack/advanced-rendering","unlisted":false},{"type":"link","label":"Distribution","href":"/Backpacked/docs/custom-backpack/distribution","docId":"custom-backpack/distribution","unlisted":false},{"type":"link","label":"Assets","href":"/Backpacked/docs/custom-backpack/assets","docId":"custom-backpack/assets","unlisted":false}],"href":"/Backpacked/docs/custom-backpack/"},{"type":"link","label":"Guides","href":"/Backpacked/docs/","docId":"index","unlisted":false}]},"docs":{"custom-backpack/advanced-rendering":{"id":"custom-backpack/advanced-rendering","title":"Advanced Rendering","description":"This guide is in development, and will be released at a later date. For now, examples can be found in the official mod resources (here and here).","sidebar":"tutorialSidebar"},"custom-backpack/assets":{"id":"custom-backpack/assets","title":"Assets","description":"Here you will find assets referenced throughout the guides. They are all placed on a single page for your convenience.","sidebar":"tutorialSidebar"},"custom-backpack/creating-the-model":{"id":"custom-backpack/creating-the-model","title":"Creating the Model","description":"Standard Template","sidebar":"tutorialSidebar"},"custom-backpack/distribution":{"id":"custom-backpack/distribution","title":"Distribution","description":"Backpacked Addons are special in the fact they are both a resource and data pack in a single ZIP file, but how do you distribute the file? Both CurseForge and Modrinth have seperate sections for reosurce packs and data packs, however Backpacked addons should be simply treated as a resource pack. This means in both the CurseForge App (standalone) and Modrinth App, Backpacked Addons can be installed with one-click into players\' game profiles.","sidebar":"tutorialSidebar"},"custom-backpack/getting-started":{"id":"custom-backpack/getting-started","title":"Getting Started","description":"Addons can be created by using Backpacked\'s addon format or writing an addon mod.","sidebar":"tutorialSidebar"},"custom-backpack/index":{"id":"custom-backpack/index","title":"Custom Backpacks","description":"This guide only applies to Backpacked 3.0 and above. Custom backpacks are not supported in prior versions.","sidebar":"tutorialSidebar"},"custom-backpack/introduction":{"id":"custom-backpack/introduction","title":"Introduction","description":"Addons for Backpacked are simply the combination of a carefully constructed resource and data pack. This has many advantages, resource and data packs are already familiar in the community, they are easy to create, can be installed via drag-and-drop, and have been highly documentated. They are also very veristile, allowing you to release them as is, in a mod, or in a modpack as default resources. Backpacked itself uses a built-in resource and data pack to add the backpacks found by default in the mod.","sidebar":"tutorialSidebar"},"custom-backpack/model-metadata":{"id":"custom-backpack/model-metadata","title":"Model Metadata","description":"Every backpack has a special JSON metadata file that is used to define properties about that backpack. This includes display properties which control how the model appears on the shelf and in the GUI. It optionally gives you the ability to completely take control of how the backpack is drawn, which is used for creating advanced models with animations.","sidebar":"tutorialSidebar"},"custom-backpack/register-the-backpack":{"id":"custom-backpack/register-the-backpack","title":"Register a New Backpack","description":"Backpack Directory","sidebar":"tutorialSidebar"},"custom-backpack/translations":{"id":"custom-backpack/translations","title":"Translations","description":"Minecraft has a directory in the assets where translations are provided. This will allow the name of a backpack to be displayed in the language players set in their game. There must be at least a US English translation (denoted by en_us) as this is the default and fallback langauge. Adding support for more languages is completely optional, you can find a list of the locale codes on the Minecraft Wiki.","sidebar":"tutorialSidebar"},"custom-backpack/unlock-challenges/challenge-types":{"id":"custom-backpack/unlock-challenges/challenge-types","title":"Challenge Types","description":"Backpacked comes with many built-in challenge types","sidebar":"tutorialSidebar"},"custom-backpack/unlock-challenges/creating-the-challenge":{"id":"custom-backpack/unlock-challenges/creating-the-challenge","title":"Creating the Challenge","description":"Getting Started","sidebar":"tutorialSidebar"},"custom-backpack/unlock-challenges/formatter-types":{"id":"custom-backpack/unlock-challenges/formatter-types","title":"Formatter Types","description":"TODO","sidebar":"tutorialSidebar"},"custom-backpack/unlock-challenges/introduction":{"id":"custom-backpack/unlock-challenges/introduction","title":"Introduction","description":"Every backpack has the option to set an unlock challenge. Unlock challenges are simply goals the player can complete in order to unlock new backpacks. They are inspired from Advancements from the vanilla game, except the main difference is that the player unlocks a reward (the backpack).","sidebar":"tutorialSidebar"},"custom-backpack/unlock-challenges/predicates":{"id":"custom-backpack/unlock-challenges/predicates","title":"Predicates","description":"List of Predicates","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"Guides","description":"","sidebar":"tutorialSidebar"}}}}')}}]);